def preserve_consumers(apps, schema_editor):
    Connector = apps.get_model('content', 'McpConnector')
    Credential = apps.get_model('content', 'McpCredential')
    now = timezone.now()
    for connector in Connector.objects.using(schema_editor.connection.alias).filter(slug__in=LEGACY_NAMES):
        connector.migration_started_at = now
        connector.save(update_fields=['migration_started_at'])
        credentials = Credential.objects.using(schema_editor.connection.alias).filter(connector=connector)
        for credential in credentials:
            credential.catalog = 'legacy'
            if not credential.allowed_tools:
                credential.allowed_tools = LEGACY_NAMES[connector.slug]
            credential.save(update_fields=['catalog', 'allowed_tools'])
        if connector.token_hash and not credentials.exists():
            Credential.objects.using(schema_editor.connection.alias).create(
                connector=connector, label='Default', catalog='legacy',
                token_hash=connector.token_hash, token_prefix=connector.token_prefix,
                allowed_tools=LEGACY_NAMES[connector.slug],
            )


